document.addEventListener("DOMContentLoaded",()=>{const t=document.querySelector(".home-hero-video-embed video");if(!t)return;const e=new Plyr(t,{controls:["play-large","play","progress","current-time","mute","volume","fullscreen"],hideControls:!1,ratio:"16:9"});window.heroPlyr=e,document.querySelector("#home-hero")?.addEventListener("click",()=>{document.querySelector(".video-popup")?.classList.add("is-active"),setTimeout(()=>e.play(),50)}),document.addEventListener("keydown",o=>{o.code==="Space"&&e.pause()}),document.querySelectorAll("[home-hero-view-video]").forEach(o=>{o?.addEventListener("click",()=>{const c=document.querySelector(".video-popup");c.classList.contains("is-active")||c.classList.add("is-active"),setTimeout(()=>e.play(),50)})}),document.querySelectorAll("[close-video-popup]").forEach(o=>{o?.addEventListener("click",()=>{e.pause(),e.currentTime=0,document.querySelector(".video-popup")?.classList.remove("is-active")})})});
